import{_ as u,a0 as l,w as d,s as r,ao as a,I as e,x as t,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 22.04 / 20.04 LTS 中重新設置 sudo 密碼 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 22.04 / 20.04 LTS 中重新設置 sudo 密碼 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 22.04 / 20.04 LTS 中重新設置 sudo 密碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 22.04 / 20.04 LTS 中重新設置 sudo 密碼 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220518 How To Reset Sudo Password In Ubuntu 22.04 - 20.04 LTS","title":"如何在 Ubuntu 22.04 / 20.04 LTS 中重新設置 sudo 密碼","tag":"202205","desc":""},"relativePath":"202205/20220518 How To Reset Sudo Password In Ubuntu 22.04 - 20.04 LTS.md","filePath":"[post].md"}'),p={name:"202205/20220518 How To Reset Sudo Password In Ubuntu 22.04 - 20.04 LTS.md"};function b(h,s,g,c,k,m){const i=l("Link");return d(),r("div",null,[s[21]||(s[21]=a('<h1 id="如何在-ubuntu-22-04-20-04-lts-中重新設置-sudo-密碼" tabindex="-1">如何在 Ubuntu 22.04 / 20.04 LTS 中重新設置 sudo 密碼 <a class="header-anchor" href="#如何在-ubuntu-22-04-20-04-lts-中重新設置-sudo-密碼" aria-label="Permalink to “如何在 Ubuntu 22.04 / 20.04 LTS 中重新設置 sudo 密碼”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/29/083429wzrvirffinihrfv5.jpg" alt=""></p><blockquote><p>在 Ubuntu 中重新設置已忘記的 root 用户的密碼</p></blockquote><p>這篇簡單的指南將向你解釋，如何在 Ubuntu 22.04 好 20.04 LTS 桌面環境中，以及從服務器版本中的 <ruby>恢復<rt>rescue</rt></ruby> 模式中重新設置 sudo 密碼。</p><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3>',5)),e("p",null,[s[1]||(s[1]=t("在 ",-1)),n(i,{href:"https://ostechnix.com/install-ubuntu-desktop/"},{default:o(()=>[...s[0]||(s[0]=[t("安裝 Ubuntu",-1)])]),_:1}),s[2]||(s[2]=t(" 時，創建的一個新用户將會帶有 ",-1)),s[3]||(s[3]=e("code",null,"sudo",-1)),s[4]||(s[4]=t(" 權限，用以執行各種各樣的管理任務。",-1))]),s[22]||(s[22]=a('<p>如果你的 Ubuntu 系統有多個 <code>sudo</code> 用户，你能夠從另外一個 <code>sudo</code> 用户的賬號下，輕鬆地重新設置所忘記的一個 <code>sudo</code> 用户或管理員用户的密碼。</p><p>如果你只有一個 <code>sudo</code> 用户，並且忘記了密碼怎麼辦？沒有問題! 從 Ubuntu 的 <ruby>恢復<rt>rescue</rt></ruby> 或 <ruby>單一用户<rt>single user</rt></ruby> 模式中恢復 <code>sudo</code> 用户密碼很容易。</p><p>雖然這篇指南是在 Ubuntu 22.04 和 20.04 LTS 版本上進行的正式測試，不過，下面給定的步驟對於其它的 Ubuntu 版本和衍生版本來説是相同的。</p><h3 id="在-ubuntu-22-04-20-04-lts-中重新設置-sudo-密碼" tabindex="-1">在 Ubuntu 22.04 / 20.04 LTS 中重新設置 sudo 密碼 <a class="header-anchor" href="#在-ubuntu-22-04-20-04-lts-中重新設置-sudo-密碼" aria-label="Permalink to “在 Ubuntu 22.04 / 20.04 LTS 中重新設置 sudo 密碼”">​</a></h3><p>首先，啓動你的 Ubuntu 系統到 <ruby>恢復<rt>rescue</rt></ruby> 模式下，來重新設置一個 <code>sudo</code> 用户的密碼，操作如下面的鏈接所述。</p>',5)),e("blockquote",null,[e("p",null,[n(i,{href:"https://ostechnix.com/how-to-boot-into-rescue-mode-or-emergency-mode-in-ubuntu-18-04/"},{default:o(()=>[...s[5]||(s[5]=[t("如何啓動到 Ubuntu 22.04 /  20.04 / 18.04 的 ",-1),e("ruby",null,[t("恢復"),e("rt",null,"rescue")],-1),t(" 模式 或 ",-1),e("ruby",null,[t("急救"),e("rt",null,"Emergency")],-1),t("模式 ",-1)])]),_:1})])]),s[23]||(s[23]=a(`<p>現在，進入到 <ruby>恢復<rt>rescue</rt></ruby> 模式下，通過運行下面的命令，以讀/寫的模式掛載根（<code>/</code>）文件系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -n -o remount,rw /</span></span></code></pre></div><p>現在，使用 <code>passwd</code> 命令來重新設置 <code>sudo</code> 用户的密碼:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># passwd ostechnix</span></span></code></pre></div><p>在這裏，<code>ostechnix</code> 是 sudo 用户的名稱。使用你自己的用户名稱來替換掉它。</p><p>輸入兩次密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>New password:</span></span>
<span class="line"><span>Retype new password:</span></span>
<span class="line"><span>passwd: password updated successfully</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Reset-Sudo-Password-In-Ubuntu.png" alt="Reset Sudo Password In Ubuntu 22.04 / 20.04 LTS"></p><p>就這樣。我們已經重新設置 <code>sudo</code> 用户密碼。如果你按照上面鏈接所述的方法 1 進入到 <ruby>恢復<rt>rescue</rt></ruby> 模式，按下 <code>Ctrl+d</code> 組合鍵來啓動到正常模式。或者，你也可以輸入下面的任意一個命令來啓動到正常模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl default</span></span></code></pre></div><p>或，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># exit</span></span></code></pre></div><p>如果你想重新啓動系統，而不是啓動到正常模式，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl reboot</span></span></code></pre></div><p>如果你已經按照上面鏈接所述的方法 2 進入到<ruby>恢復<rt>rescue</rt></ruby> 模式，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># exit</span></span></code></pre></div><p>你將返回到 <ruby>恢復菜單<rt>recovery menu</rt></ruby>。現在選擇 “<ruby>恢復正常啓動<rt>Resume normal boot</rt></ruby>”，並按下回車鍵。</p><p><img src="https://ostechnix.com/wp-content/uploads/2020/05/Boot-into-normal-mode-in-Ubuntu.png" alt="Boot Into Normal Mode In Ubuntu"></p><p>在強調一次，選擇 “<ruby>確定<rt>OK</rt></ruby>” 按鈕，並按下回車按鍵來繼續啓動到正常模式：</p><p><img src="https://ostechnix.com/wp-content/uploads/2020/05/Booting-into-normal-mode-from-rescue-mode-in-Ubuntu.png" alt="Exit Recovery Mode And Boot Into Normal Mode"></p><p>現在，你在運行管理命令時可以使用新的 <code>sudo</code> 密碼。</p><h3 id="如果我把用户名稱和密碼都忘了怎麼辦" tabindex="-1">如果我把用户名稱和密碼都忘了怎麼辦？ <a class="header-anchor" href="#如果我把用户名稱和密碼都忘了怎麼辦" aria-label="Permalink to “如果我把用户名稱和密碼都忘了怎麼辦？”">​</a></h3><p>如果你忘記了用户名稱，在 <ruby>恢復<rt>rescue</rt></ruby> 模式下，你可以很容易地列出你的 Linux 系統中的用户名稱，使用目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat etc/passwd</span></span></code></pre></div><p>來自我 Ubuntu 22.04 系統的輸出示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[...]</span></span>
<span class="line"><span>ostechnix:x:1000:1000:Ostechnix,,,:/home/ostechnix:/bin/bash</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>好了，現在，你找到用户名稱了。只需要按照上面的步驟來重新設置用户的密碼即可。</p><hr>`,28)),e("p",null,[s[7]||(s[7]=t("via: ",-1)),n(i,{href:"https://ostechnix.com/how-to-reset-sudo-password-in-ubuntu-20-04-lts/"},{default:o(()=>[...s[6]||(s[6]=[t("https://ostechnix.com/how-to-reset-sudo-password-in-ubuntu-20-04-lts/",-1)])]),_:1})]),e("p",null,[s[12]||(s[12]=t("作者：",-1)),n(i,{href:"https://ostechnix.com/author/sk/"},{default:o(()=>[...s[8]||(s[8]=[t("sk",-1)])]),_:1}),s[13]||(s[13]=t(" 選題：",-1)),n(i,{href:"https://github.com/lkxed"},{default:o(()=>[...s[9]||(s[9]=[t("lkxed",-1)])]),_:1}),s[14]||(s[14]=t(" 譯者：",-1)),n(i,{href:"https://github.com/robsean"},{default:o(()=>[...s[10]||(s[10]=[t("robsean",-1)])]),_:1}),s[15]||(s[15]=t(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:o(()=>[...s[11]||(s[11]=[t("wxy",-1)])]),_:1})]),e("p",null,[s[18]||(s[18]=t("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[16]||(s[16]=[t("LCTT",-1)])]),_:1}),s[19]||(s[19]=t(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:o(()=>[...s[17]||(s[17]=[t("Linux中國",-1)])]),_:1}),s[20]||(s[20]=t(" 榮譽推出",-1))])])}const x=u(p,[["render",b]]);export{T as __pageData,x as default};
